import type { PromptLanguage } from './types';

export interface AssessmentPromptPack { system: string; purpose: string; emptyInput: string }
export interface AuthorPromptPack { system: string; author: string; themes: string; ideas: string; relations: string; noRelations: string; returnJson: string; ideaTypes: Record<string, string>; relationTypes: Record<string, string> }
export interface ChapterPromptPack { extract: string; type: string; embeddingType: string; embeddingLabel: string; embeddingStatement: string }
export interface DocumentProfilePromptPack { section: string; reduce: string; sectionAudit: string; profile: string; audit: string; repair: string }
export interface FolderPromptPack { system: string; folderSummary: string; candidates: string; returnJson: string; fallback: string }
export interface GapPromptPack { system: string; gap: string; works: string; returnJson: string }
export interface DictionaryPromptPack { system: string; authorSystem: string; concept: string; aliases: string; focus: string; detail: string; outputLanguage: string; current: string; correction: string; evidence: string }

/** Runtime copy used while assembling Dictionary evidence, retries, and safe fallbacks. */
export interface DictionaryRuntimeCopy {
  coverageHeader: string;
  coverageAuthors: string;
  coverageWorks: string;
  coverageNoAuthors: string;
  coverageNoWorks: string;
  coverageAuthorRow: (name: string, works: string, refs: string) => string;
  coverageWorkRow: (title: string, authors: string, refs: string) => string;
  evidenceCitationLabel: string;
  citationIdeaPrefix: string;
  citationSourceFallback: string;
  insufficientTitle: string;
  insufficientIntro: string;
  insufficientLimits: string;
  groundingEmpty: string;
  groundingNoCitation: string;
  groundingUncited: (count: number) => string;
  coverageWorksProblem: (used: number, available: number, target: number) => string;
  coverageAuthorsProblem: (used: number, available: number, target: number) => string;
  retryRejected: (attempt: number, problems: string) => string;
  retryRewrite: string;
  retryAtomic: string;
  retryCoverage: string;
  retrySemantic: (sentences: string) => string;
  semanticRejected: (count: number) => string;
  invalidEvidence: (count: number) => string;
  degradedFallbackTitle: string;
  noEntryError: string;
  noEvidenceError: string;
}

export interface DictionaryScaffoldPack {
  none: string;
  authors: string;
  verifiedDescription: string;
  retryInvalidJson: string;
  retryReturnObject: string;
  retryShorten: string;
}

