export function dictionaryScaffoldPack(language: PromptLanguage = 'es'): DictionaryScaffoldPack {
  return DICTIONARY_SCAFFOLD_PACKS[language] ?? DICTIONARY_SCAFFOLD_PACKS.es;
}

