    fr: { sharedThemes: 'thèmes communs', noIdeas: 'aucune idée enregistrée' },
    de: { sharedThemes: 'gemeinsame Themen', noIdeas: 'keine Ideen erfasst' },
    pt: { sharedThemes: 'temas comuns', noIdeas: 'sem ideias registadas' },
    'pt-BR': { sharedThemes: 'temas em comum', noIdeas: 'nenhuma ideia registrada' },
