export function documentProfilePromptPack(language: PromptLanguage = 'es'): DocumentProfilePromptPack {
  const selectedLanguage = DOCUMENT_PROFILE_PROMPT_PACKS[language] ? language : 'es';
  const pack = DOCUMENT_PROFILE_PROMPT_PACKS[selectedLanguage];
  const extension = DOCUMENT_PROFILE_FIELD_EXTENSIONS[selectedLanguage];
  return {
    ...pack,
    profile: `${pack.profile}\n${extension.profile}`,
    audit: `${pack.audit}\n${extension.audit}`,
    repair: `${pack.repair}\n${extension.repair}`,
  };
}
export function folderPromptPack(language: PromptLanguage = 'es'): FolderPromptPack { return FOLDER_PROMPT_PACKS[language] ?? FOLDER_PROMPT_PACKS.es; }
export function gapPromptPack(language: PromptLanguage = 'es'): GapPromptPack { return GAP_PROMPT_PACKS[language] ?? GAP_PROMPT_PACKS.es; }
export function dictionaryPromptPack(language: PromptLanguage = 'es'): DictionaryPromptPack { return DICTIONARY_PROMPT_PACKS[language] ?? DICTIONARY_PROMPT_PACKS.es; }
